SELECT (SELECT group_concat(name, ',') FROM (SELECT name FROM pragma_table_info('t1') ORDER BY cid)) AS t1_columns, (SELECT group_concat(name, ',') FROM (SELECT name FROM pragma_table_info('t2') ORDER BY cid)) AS t2_columns, (SELECT group_concat(name, ',') FROM (SELECT name FROM pragma_index_info('i1') ORDER BY seqno)) AS i1_columns, (SELECT group_concat(name, ',') FROM (SELECT name FROM pragma_index_info('i2') ORDER BY seqno)) AS i2_columns, (SELECT [unique] FROM pragma_index_list('t1') WHERE name='i1') AS i1_unique, (SELECT [unique] FROM pragma_index_list('t2') WHERE name='i2') AS i2_unique, (SELECT count(*) FROM sqlite_schema WHERE name IN ('t1','t2','i1','i2')) AS object_count;